package com.pocketmusic.android;
import android.app.*;import android.content.*;import android.os.*;import android.view.accessibility.AccessibilityNodeInfo;import android.widget.ImageButton;import androidx.test.platform.app.InstrumentationRegistry;import org.junit.*;import java.io.*;import java.lang.reflect.*;import java.util.*;import java.nio.*;import static org.junit.Assert.*;
public class DownloadExperienceTest {
 private Instrumentation test;private Context c;private TestMusicFixtures.Snapshot snapshot;private Object originalQueue;private String originalStatus;private AccountMusic.Source oldSource;private MainActivity activity;private File file;
 @Before public void setup()throws Exception{test=InstrumentationRegistry.getInstrumentation();c=test.getTargetContext();Assume.assumeFalse(YouTubeSession.connected(c));Assume.assumeFalse(DownloadService.busy);Assume.assumeFalse(LocalPlayerService.active!=null&&LocalPlayerService.active.playing());snapshot=new TestMusicFixtures.Snapshot(c);originalQueue=field(DownloadService.class,"queue").get(null);originalStatus=DownloadService.status;oldSource=Recommendations.accountSource;if(Build.VERSION.SDK_INT>=33)test.getUiAutomation().grantRuntimePermission(c.getPackageName(),android.Manifest.permission.POST_NOTIFICATIONS);NotificationManager manager=c.getSystemService(NotificationManager.class);manager.createNotificationChannel(new NotificationChannel("downloads","Downloads",NotificationManager.IMPORTANCE_LOW));manager.createNotificationChannel(new NotificationChannel("download-results","Download results",NotificationManager.IMPORTANCE_DEFAULT));}
 @After public void cleanup()throws Exception{if(snapshot==null)return;test.runOnMainSync(()->{c.stopService(new Intent(c,LocalPlayerService.class));c.stopService(new Intent(c,DownloadService.class));if(activity!=null)activity.finish();});long end=System.currentTimeMillis()+5000;while(field(DownloadService.class,"active").get(null)!=null&&System.currentTimeMillis()<end)Thread.sleep(50);Recommendations.accountSource=oldSource;field(DownloadService.class,"queue").set(null,originalQueue);DownloadService.status=originalStatus;if(file!=null)file.delete();for(int id:new int[]{20,21,50020,50021})c.getSystemService(NotificationManager.class).cancel(id);YouTubeSession.disconnect(c);test.waitForIdleSync();if(snapshot!=null)snapshot.restore();}
 private Field field(Class<?> type,String name)throws Exception{Field f=type.getDeclaredField(name);f.setAccessible(true);return f;}
 private DownloadQueue queue()throws Exception{DownloadQueue q=new DownloadQueue(2);field(DownloadService.class,"queue").set(null,q);return q;}
 private File audio()throws Exception{File target=new File(MusicRepository.folder(c),"Completed sample [exp00000002].mp3");int samples=22050*10;ByteBuffer b=ByteBuffer.allocate(44+samples*2).order(ByteOrder.LITTLE_ENDIAN);b.put("RIFF".getBytes()).putInt(36+samples*2).put("WAVEfmt ".getBytes()).putInt(16).putShort((short)1).putShort((short)1).putInt(22050).putInt(44100).putShort((short)2).putShort((short)16).put("data".getBytes()).putInt(samples*2);try(OutputStream out=new FileOutputStream(target)){out.write(b.array());}return target;}
 @Test public void zeroPercentAndUnknownProgressHaveDifferentNotificationStates(){DownloadQueue.Job j=new DownloadQueue.Job("exp00000001","Downloading sample","mp3");j.state="running";j.progress=0;Notification known=DownloadNotifications.active(c,List.of(j));assertFalse(known.extras.getBoolean(Notification.EXTRA_PROGRESS_INDETERMINATE));assertEquals(0,known.extras.getInt(Notification.EXTRA_PROGRESS));assertEquals(2,known.actions.length);j.progress=-1;assertTrue(DownloadNotifications.active(c,List.of(j)).extras.getBoolean(Notification.EXTRA_PROGRESS_INDETERMINATE));}
 @Test public void signedInAvatarNotificationTapFiltersAndHistoryOperateOnTheExistingActivity()throws Exception{
  SessionAuth account=SessionAuth.capture("SAPISID=synthetic; __Secure-3PSID=synthetic","fixture-visitor","fixture-channel","0","1.fixture").identity("Fixture listener").avatar("https://lh3.googleusercontent.com/a/fixture");YouTubeSession.save(c,account);c.getSharedPreferences("music",0).edit().putString("avatarCheckedScope",YouTubeSession.fingerprint(c)).putLong("avatarCheckedAt",System.currentTimeMillis()).commit();List<Track> songs=List.of(TestMusicFixtures.song("abcdefghijk","Fixture song","Fixture artist"));Recommendations.accountSource=(context,p)->List.of(new DiscoveryShelf("Account picks","Account",songs));Recommendations.save(c,Recommendations.scope(c),MusicTaste.version(c),List.of(new DiscoveryShelf("Account picks","Account",songs)),0,"account");
  DownloadQueue q=queue();DownloadQueue.Job running=q.enqueue("exp00000001","Downloading sample","mp3"),done=q.enqueue("exp00000002","Completed sample","mp3"),failed=q.enqueue("exp00000003","Needs retry sample","mp3");running.state="running";running.progress=42;running.speed="512 KiB/s";running.etaSeconds=60;done.state="done";failed.state="failed";failed.message="Connection interrupted";failed.error="Synthetic network failure";file=audio();
  activity=(MainActivity)test.startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));long end=System.currentTimeMillis()+7000;ImageButton avatar=(ImageButton)field(MainActivity.class,"accountAvatar").get(activity);while(!String.valueOf(avatar.getContentDescription()).contains("Fixture listener")&&System.currentTimeMillis()<end)Thread.sleep(80);assertTrue(String.valueOf(avatar.getContentDescription()).contains("Fixture listener"));assertTrue(avatar.getClipToOutline());if("true".equals(InstrumentationRegistry.getArguments().getString("experienceScreen")))capture("signed-in-home");test.runOnMainSync(avatar::performClick);await("YouTube account");assertFalse(test.getUiAutomation().getRootInActiveWindow().findAccessibilityNodeInfosByText("Connected as Fixture listener").isEmpty());click("Close");String originalScope=YouTubeSession.fingerprint(c);YouTubeSession.save(c,YouTubeSession.read(c).identity("Updated listener").avatar(account.avatarUrl));assertEquals(originalScope,YouTubeSession.fingerprint(c));test.runOnMainSync(()->{try{Method update=MainActivity.class.getDeclaredMethod("refreshAccountAvatar");update.setAccessible(true);update.invoke(activity);}catch(Exception e){throw new AssertionError(e);}});end=System.currentTimeMillis()+7000;while(!String.valueOf(avatar.getContentDescription()).contains("Updated listener")&&System.currentTimeMillis()<end)Thread.sleep(80);assertTrue(String.valueOf(avatar.getContentDescription()).contains("Updated listener"));
  NotificationManager manager=c.getSystemService(NotificationManager.class);Notification notice=DownloadNotifications.active(c,q.all());manager.notify(50020,notice);notice.contentIntent.send();await("Downloads");Object sheet=field(MainActivity.class,"downloadsDialog").get(activity);assertNotNull("Existing Activity must handle the notification intent",sheet);await("Downloading sample");await("Completed sample");await("Needs retry sample");if("true".equals(InstrumentationRegistry.getArguments().getString("experienceScreen")))capture("downloads-all");click("Active");await("Downloading sample");assertNull(find("Completed sample"));click("Clear history");assertEquals(1,q.all().size());assertTrue(file.exists());
  Notification result=DownloadNotifications.finished(c,List.of(done));assertNotNull(result);assertEquals(0,result.flags&Notification.FLAG_ONGOING_EVENT);assertEquals(2,result.actions.length);manager.notify(50021,result);if("true".equals(InstrumentationRegistry.getArguments().getString("experienceScreen"))){capture("downloads-active");}
  result.actions[1].actionIntent.send();end=System.currentTimeMillis()+7000;while((LocalPlayerService.active==null||!LocalPlayerService.active.playing())&&System.currentTimeMillis()<end)Thread.sleep(80);assertNotNull(LocalPlayerService.active);assertTrue("Completion notification Play must start saved audio",LocalPlayerService.active.playing());
 }
 @Test public void realSaveOnlyRetryProducesAnAttentionNotificationAndStopsForegroundWork()throws Exception{Assume.assumeFalse(DownloadFolder.hasAccess(c));DownloadQueue q=queue();DownloadQueue.Job job=q.enqueue("exp00000002","Completed sample","mp3");job.state="saveFailed";file=audio();c.startForegroundService(new Intent(c,DownloadService.class).setAction("retry").putExtra("job",job.key));long end=System.currentTimeMillis()+10000;boolean result=false;while(System.currentTimeMillis()<end){for(android.service.notification.StatusBarNotification n:c.getSystemService(NotificationManager.class).getActiveNotifications())if(n.getId()==21){result=true;assertTrue(n.getNotification().extras.getCharSequence(Notification.EXTRA_TITLE).toString().contains("attention"));assertEquals("Retry",n.getNotification().actions[0].title.toString());}if(result&&!DownloadService.busy&&field(DownloadService.class,"active").get(null)==null)break;Thread.sleep(80);}assertTrue(result);assertEquals("saveFailed",job.state);assertTrue(job.saveOnly);assertTrue(file.exists());}
 private AccessibilityNodeInfo find(String text){AccessibilityNodeInfo root=test.getUiAutomation().getRootInActiveWindow();if(root!=null)for(AccessibilityNodeInfo n:root.findAccessibilityNodeInfosByText(text))if(n.getText()!=null&&text.equalsIgnoreCase(n.getText().toString()))return n;return null;}
 private AccessibilityNodeInfo await(String text)throws Exception{long end=System.currentTimeMillis()+7000;while(System.currentTimeMillis()<end){AccessibilityNodeInfo node=find(text);if(node!=null)return node;Thread.sleep(80);}throw new AssertionError("Missing UI: "+text);}
 private void click(String text)throws Exception{AccessibilityNodeInfo node=await(text);while(!node.isClickable()&&node.getParent()!=null)node=node.getParent();assertTrue(node.performAction(AccessibilityNodeInfo.ACTION_CLICK));test.waitForIdleSync();Thread.sleep(150);}
 private void capture(String name)throws Exception{test.waitForIdleSync();Thread.sleep(500);android.graphics.Bitmap screen=test.getUiAutomation().takeScreenshot();File folder=new File(c.getExternalFilesDir(null),"screens");folder.mkdirs();try(OutputStream out=new FileOutputStream(new File(folder,name+".png"))){screen.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}screen.recycle();}
}
